<?php
namespace App\Services; use App\Core\Database; use RuntimeException; class LedgerService{public function post(string $refType,int $refId,string $description,array $entries):int{$debit=0;$credit=0;foreach($entries as $e){$debit+=(float)($e['debit']??0);$credit+=(float)($e['credit']??0);} if(round($debit,2)!==round($credit,2)||$debit<=0)throw new RuntimeException('سند حسابداری تراز نیست.');$db=Database::pdo();$db->beginTransaction();try{$s=$db->prepare('INSERT INTO ledger_entries(reference_type,reference_id,description,total_debit,total_credit,created_by) VALUES(?,?,?,?,?,?)');$s->execute([$refType,$refId,$description,$debit,$credit,$_SESSION['user']['id']??null]);$id=(int)$db->lastInsertId();$i=$db->prepare('INSERT INTO ledger_lines(ledger_entry_id,account_code,account_title,debit,credit,party_id) VALUES(?,?,?,?,?,?)');foreach($entries as $e)$i->execute([$id,$e['account_code'],$e['account_title'],$e['debit']??0,$e['credit']??0,$e['party_id']??null]);$db->commit();return $id;}catch(\Throwable $e){$db->rollBack();throw $e;}}}
